-- Reposts, and shared Community parlays as posts.
--
-- post_reposts: one row per repost ("retweet").
-- posts.parlay_id: a shared parlay is carried by a post, so it is liked,
-- replied to and reposted through the same tables as every other post. Such a
-- post may have an empty body — the ticket is the content.
--
-- Generated by drizzle-kit; the backfill at the end is added by hand: every
-- parlay already shared gets its post, dated when it was built, so nothing
-- moves in anyone's timeline.
CREATE TABLE "post_reposts" (
	"user_id" uuid NOT NULL,
	"post_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "post_reposts_user_id_post_id_pk" PRIMARY KEY("user_id","post_id")
);
